// Minimal server-side Lago client. Never import from client components.
import { createHmac, createPublicKey, timingSafeEqual, verify } from "node:crypto";

const API_URL = (process.env.LAGO_API_URL ?? "").replace(/\/+$/, "");
const API_KEY = process.env.LAGO_API_KEY ?? "";
const TIMEOUT_MS = 10_000;
const MAX_RETRIES = 4;

export class LagoError extends Error {
  constructor(message: string, readonly status: number | null, readonly body: unknown, readonly retryable: boolean) {
    super(message);
  }
}

/** 422 on an event whose transaction_id already exists. Not a success: reconcile before marking delivered. */
export class LagoDuplicateEventError extends LagoError {}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const backoff = (attempt: number) => Math.min(8000, 250 * 2 ** attempt) * (0.5 + Math.random());

async function request<T>(method: "GET" | "POST", path: string, body?: unknown): Promise<T> {
  if (!API_URL || !API_KEY) throw new LagoError("LAGO_API_URL and LAGO_API_KEY must be set", null, null, false);

  for (let attempt = 0; ; attempt++) {
    let error: LagoError;
    try {
      const res = await fetch(`${API_URL}/api/v1${path}`, {
        method,
        headers: { Authorization: `Bearer ${API_KEY}`, "Content-Type": "application/json" },
        body: body === undefined ? undefined : JSON.stringify(body),
        signal: AbortSignal.timeout(TIMEOUT_MS),
      });
      const text = await res.text();
      const json = text ? safeJson(text) : null;
      if (res.ok) return json as T;

      const retryable = res.status === 429 || res.status >= 500;
      if (res.status === 422 && isDuplicateTransaction(json)) {
        throw new LagoDuplicateEventError("Lago event transaction_id already exists", 422, json, false);
      }
      error = new LagoError(`Lago ${method} ${path} failed with ${res.status}`, res.status, json, retryable);
    } catch (e) {
      if (e instanceof LagoError) throw e;
      // Network error or timeout.
      error = new LagoError(`Lago ${method} ${path} failed: ${(e as Error).message}`, null, null, true);
    }
    if (!error.retryable || attempt >= MAX_RETRIES) throw error;
    await sleep(backoff(attempt));
  }
}

function safeJson(text: string): unknown {
  try { return JSON.parse(text); } catch { return text; }
}

function isDuplicateTransaction(json: unknown): boolean {
  const details = (json as { error_details?: { transaction_id?: unknown } } | null)?.error_details?.transaction_id;
  return Array.isArray(details) && details.includes("value_already_exist");
}

// --- Customers & subscriptions ---------------------------------------------

export function upsertCustomer(c: { externalId: string; name: string; email: string; currency?: string }) {
  return request("POST", "/customers", {
    customer: { external_id: c.externalId, name: c.name, email: c.email, currency: c.currency ?? "USD" },
  });
}

export function createSubscription(s: { externalId: string; externalCustomerId: string; planCode: string }) {
  return request("POST", "/subscriptions", {
    subscription: { external_id: s.externalId, external_customer_id: s.externalCustomerId, plan_code: s.planCode },
  });
}

// --- Usage -----------------------------------------------------------------

export type UsageEvent = {
  /** Stable id derived from the durable source record; reuse it on every retry. */
  transactionId: string;
  externalSubscriptionId: string;
  code: string;
  /** Time the usage happened. Resend unchanged on retry. */
  occurredAt: Date;
  properties: Record<string, string | number>;
};

export function sendEvent(e: UsageEvent) {
  return request("POST", "/events", {
    event: {
      transaction_id: e.transactionId,
      external_subscription_id: e.externalSubscriptionId,
      code: e.code,
      timestamp: (e.occurredAt.getTime() / 1000).toFixed(3),
      properties: e.properties,
    },
  });
}

export type CurrentUsage = {
  customer_usage: {
    amount_cents: number;
    currency: string;
    charges_usage: { units: string; amount_cents: number; billable_metric: { code: string } }[];
  };
};

export function getCurrentUsage(externalCustomerId: string, externalSubscriptionId: string) {
  return request<CurrentUsage>(
    "GET",
    `/customers/${encodeURIComponent(externalCustomerId)}/current_usage?external_subscription_id=${encodeURIComponent(externalSubscriptionId)}`,
  );
}

// --- Webhooks --------------------------------------------------------------

let publicKeyPem: Promise<string> | null = null;
function getWebhookPublicKey() {
  publicKeyPem ??= request<{ webhook: { public_key: string } }>("GET", "/webhooks/json_public_key")
    .then((r) => Buffer.from(r.webhook.public_key, "base64").toString("utf8"))
    .catch((e) => { publicKeyPem = null; throw e; });
  return publicKeyPem;
}

/** Verify a Lago webhook against the raw request body (never re-serialized JSON). */
export async function verifyWebhook(rawBody: string, headers: Headers): Promise<boolean> {
  const signature = headers.get("x-lago-signature");
  const algorithm = headers.get("x-lago-signature-algorithm");
  if (!signature) return false;

  if (algorithm === "hmac") {
    const key = process.env.LAGO_WEBHOOK_HMAC_KEY;
    if (!key) return false;
    const expected = Buffer.from(createHmac("sha256", key).update(rawBody).digest("base64"));
    const given = Buffer.from(signature);
    return expected.length === given.length && timingSafeEqual(expected, given);
  }

  if (algorithm === "jwt") {
    const [h, p, s] = signature.split(".");
    if (!h || !p || !s) return false;
    const header = safeJson(Buffer.from(h, "base64url").toString()) as { alg?: string } | null;
    if (header?.alg !== "RS256") return false;
    const ok = verify("RSA-SHA256", Buffer.from(`${h}.${p}`), createPublicKey(await getWebhookPublicKey()), Buffer.from(s, "base64url"));
    if (!ok) return false;
    const payload = safeJson(Buffer.from(p, "base64url").toString()) as { iss?: string; data?: string } | null;
    return payload?.iss === API_URL && payload?.data === rawBody;
  }

  return false;
}

// Stand-in for the app's database.
export type Workspace = { id: string; name: string; email: string; plan: "free" | "pro" };
export type Generation = { id: string; workspaceId: string; model: string; inputTokens: number; outputTokens: number; createdAt: Date };
// Outbox row for a usage event; written in the same transaction as the generation.
export type UsageOutbox = {
  transactionId: string;
  externalSubscriptionId: string;
  code: string;
  occurredAt: Date;
  properties: Record<string, string | number>;
  status: "pending" | "delivered" | "needs_reconciliation" | "failed";
  attempts: number;
  lastError?: string;
};
export type LagoWebhookEvent = { uniqueKey: string; type: string; payload: unknown; receivedAt: Date; processedAt?: Date };
export const db = {
  workspaces: new Map<string, Workspace>(),
  generations: new Map<string, Generation>(),
  usageOutbox: new Map<string, UsageOutbox>(),
  lagoWebhookEvents: new Map<string, LagoWebhookEvent>(),
};

// App-side billing glue. Lago owns metering, pricing and invoices; the app owns
// identity, durable usage records, delivery and access decisions.
import { db, type Generation, type Workspace } from "@/lib/db";
import { createSubscription, LagoDuplicateEventError, LagoError, sendEvent, upsertCustomer } from "@/lib/lago";

export const LAGO_PLAN_CODE = "pro";
export const TOKENS_METRIC_CODE = "llm_tokens";

// Customer and subscription ids are deliberately distinct.
export const lagoCustomerId = (workspaceId: string) => workspaceId;
export const lagoSubscriptionId = (workspaceId: string) => `sub_${workspaceId}`;

/** Call at signup / upgrade to Pro. Idempotent: customers upsert on external_id. */
export async function provisionBilling(workspace: Workspace) {
  await upsertCustomer({ externalId: lagoCustomerId(workspace.id), name: workspace.name, email: workspace.email });
  if (workspace.plan === "pro") {
    try {
      await createSubscription({
        externalId: lagoSubscriptionId(workspace.id),
        externalCustomerId: lagoCustomerId(workspace.id),
        planCode: LAGO_PLAN_CODE,
      });
    } catch (e) {
      // Re-provisioning an existing subscription returns 422; anything else is real.
      if (!(e instanceof LagoError && e.status === 422)) throw e;
    }
  }
}

/** Record billable usage for a generation. Call alongside persisting the generation. */
export function recordGenerationUsage(generation: Generation) {
  const workspace = db.workspaces.get(generation.workspaceId);
  if (workspace?.plan !== "pro") return; // Only Pro workspaces have a Lago subscription.

  db.usageOutbox.set(generation.id, {
    transactionId: generation.id, // durable source record id, reused on every retry
    externalSubscriptionId: lagoSubscriptionId(generation.workspaceId),
    code: TOKENS_METRIC_CODE,
    occurredAt: generation.createdAt, // fixed timestamp, resent unchanged
    properties: { tokens: generation.inputTokens + generation.outputTokens, model: generation.model },
    status: "pending",
    attempts: 0,
  });
}

/** Worker: deliver pending usage events to Lago. Run on a schedule. */
export async function deliverPendingUsage(limit = 100) {
  const pending = [...db.usageOutbox.values()].filter((r) => r.status === "pending").slice(0, limit);
  const result = { delivered: 0, needsReconciliation: 0, failed: 0, retryLater: 0 };

  for (const row of pending) {
    row.attempts++;
    try {
      await sendEvent(row);
      row.status = "delivered";
      result.delivered++;
    } catch (e) {
      row.lastError = (e as Error).message;
      if (e instanceof LagoDuplicateEventError) {
        // A duplicate is not a success: confirm the original was ingested with the same payload.
        row.status = "needs_reconciliation";
        result.needsReconciliation++;
      } else if (e instanceof LagoError && !e.retryable) {
        row.status = "failed"; // contract error (e.g. 422); needs a human
        result.failed++;
      } else {
        result.retryLater++; // transient; the client already retried with backoff
      }
    }
  }
  return result;
}

import { recordGenerationUsage } from "@/lib/billing";
import { db } from "@/lib/db";
import { summarize } from "@/lib/llm";

export async function POST(request: Request) {
  const { workspaceId, text } = await request.json();
  const result = await summarize(text);
  const generation = {
    id: crypto.randomUUID(),
    workspaceId,
    model: result.model,
    inputTokens: result.usage.input_tokens,
    outputTokens: result.usage.output_tokens,
    createdAt: new Date(),
  };
  // In a real DB, write both rows in one transaction.
  db.generations.set(generation.id, generation);
  recordGenerationUsage(generation);
  return Response.json({ summary: result.summary });
}

import { db } from "@/lib/db";
import { verifyWebhook } from "@/lib/lago";

export const runtime = "nodejs";

export async function POST(request: Request) {
  const rawBody = await request.text(); // verify raw bytes, never re-serialized JSON
  if (!(await verifyWebhook(rawBody, request.headers))) return new Response(null, { status: 401 });

  const uniqueKey = request.headers.get("x-lago-unique-key");
  if (!uniqueKey) return new Response(null, { status: 400 });

  if (!db.lagoWebhookEvents.has(uniqueKey)) {
    const payload = JSON.parse(rawBody) as { webhook_type?: string };
    // Store durably first; process asynchronously (e.g. invoice.created, wallet updates) from a worker.
    db.lagoWebhookEvents.set(uniqueKey, { uniqueKey, type: payload.webhook_type ?? "unknown", payload, receivedAt: new Date() });
  }
  return new Response(null, { status: 204 });
}

import { deliverPendingUsage } from "@/lib/billing";

export const runtime = "nodejs";

// Trigger from a scheduler (e.g. Vercel Cron) with `Authorization: Bearer $CRON_SECRET`.
export async function POST(request: Request) {
  const secret = process.env.CRON_SECRET;
  if (!secret || request.headers.get("authorization") !== `Bearer ${secret}`) {
    return new Response(null, { status: 401 });
  }
  return Response.json(await deliverPendingUsage());
}

import { lagoCustomerId, lagoSubscriptionId } from "@/lib/billing";
import { getCurrentUsage } from "@/lib/lago";

export const runtime = "nodejs";

// Current-period usage and amount for a workspace, as computed by Lago.
// TODO: authorize that the caller belongs to the workspace.
export async function GET(request: Request) {
  const workspaceId = new URL(request.url).searchParams.get("workspaceId");
  if (!workspaceId) return new Response("workspaceId required", { status: 400 });
  const { customer_usage } = await getCurrentUsage(lagoCustomerId(workspaceId), lagoSubscriptionId(workspaceId));
  return Response.json(customer_usage);
}

